VALUES('3f219bc189f941cb9ba8e81a25a60e33','产品开放周期低于90天的开放式产品投资无活跃交易市场且需要采用估值技术确定公允价值的资产需要小于50%','LIMIT_CONCENT','${WHYJYSCGZJSQDGYJZCCSZ}/${CPJZCJZ}','SUPERVISION','01,02,03','DAYTIME,DAYEND', null , '{"threshold_1":{"op":">=","value":"48","unit":"PERCENT","is_model":"02"}}' , '{"threshold_1":{"op":">=","unit":"PERCENT","is_model":"02"}}'  , '{"threshold_1":{"op":">=","value":"50","unit":"PERCENT","is_model":"02"}}' , 'N' , null , '01' , null ,'system',null,sysdate,'system',sysdate, '02' , null , null , null  , null , null  , 'Y' , '《理财公司理财产品流动性风险管理办法》中国银行保险监督管理委员会令〔2021〕14号第十七条 单只理财产品同时存在以下情形的，应当采用封闭或定期开放运作方式，且定期开放周期不得低于90天，该理财产品销售文件还应当作出充分披露和显著标识： （一）计划投资不存在活跃交易市场，并且需要采用估值技术确定公允价值的资产； （二）计划投资上述资产的比例达到理财产品净资产50%以上。 对于其他理财产品，非因理财公司主观因素导致突破前款规定比例限制的，该理财产品不得新增投资上述资产。' , 'SUP097087' );
